import{_ as e,o as l,c as t,O as i}from"./chunks/framework.ccd0435f.js";const r="/pms-doc/assets/ygxx.ac9dfb19.png",_=JSON.parse('{"title":"员工权限","description":"","frontmatter":{},"headers":[],"relativePath":"基础设置/公司信息/员工权限.md","filePath":"基础设置/公司信息/员工权限.md"}'),o={name:"基础设置/公司信息/员工权限.md"};function s(n,a,p,c,d,h){return l(),t("div",null,a[0]||(a[0]=[i('<h1 id="员工权限" tabindex="-1">员工权限 <a class="header-anchor" href="#员工权限" aria-label="Permalink to &quot;员工权限&quot;">​</a></h1><blockquote><p>员工权限是管理信息系统或人事管理系统中的一个关键组成部分，它主要负责存储、管理和维护员工的基本信息，以及提供相关的数据支持和查询功能，（以基础设置-人员信息中的数据为准，同步至员工档案）</p><p>点击编辑可配置员工的权限等级，高级管理员可配置所有员工权限，管理员可配置，普通员工，运营管理员，普通管理员，</p></blockquote><h4 id="_1-新增人员" tabindex="-1">1. 新增人员 <a class="header-anchor" href="#_1-新增人员" aria-label="Permalink to &quot;1. 新增人员&quot;">​</a></h4><ul><li><p>可以新增人员信息也可以批量导入员工信息，可以启用员工信息或停用，在停用的情况下是不可以编辑员工信息的，停用时系统内不显该员工的信息资料</p></li><li><p>新增员工时，如果员工档案中不存在此人的人员信息，人员信息同步至员工档案（姓名，手机号，岗位，启停状态[在职/离职]）</p></li><li><p>新增员工时，如果员工档案中存在此人员信息，当人员信息进行了修改（姓名或电话与员工档案中记录数据至少有一个信息不同），更新人员信息至员工档案（姓名、手机号、岗位、工作上级）</p></li></ul><h4 id="_2-是否启用" tabindex="-1">2.是否启用 <a class="header-anchor" href="#_2-是否启用" aria-label="Permalink to &quot;2.是否启用&quot;">​</a></h4><ul><li><p>启用的情况下这个员工可登录系统，不启用的情况下员工无法登录账号</p></li><li><p>在停用的情况下是不可以编辑员工信息的，停用时系统内不显该员工的信息资料</p></li><li><p>修改员工启停状态时，也将状态同步至员工档案表中的在职离职字段，其他界面涉及员工信息弹窗会显示离职状态</p></li></ul><h4 id="_3-批量导入" tabindex="-1">3.批量导入 <a class="header-anchor" href="#_3-批量导入" aria-label="Permalink to &quot;3.批量导入&quot;">​</a></h4><ul><li>点击批量导入，下载模板，编辑模板后上传即可</li></ul><h4 id="_4-编辑" tabindex="-1">4.编辑 <a class="header-anchor" href="#_4-编辑" aria-label="Permalink to &quot;4.编辑&quot;">​</a></h4><ul><li>点击编辑可更改员工的姓名、电话、岗位、工作上级、权限等级，提交后同步至员工档案（姓名、电话、岗位、工作上级）</li></ul><p><img src="'+r+'" alt="如图所示"></p>',11)]))}const m=e(o,[["render",s]]);export{_ as __pageData,m as default};
